import { Effect } from "effect"
import { resolveWorkspace, loadPreviewConfig, uploadPreview, previewUrl } from "./_common.ts"

export interface CreatePreviewOptions {
  readonly directory: string
  readonly branch: string
  readonly expiresInHours: number
}

export const createPreview = Effect.fn("Preview.create")(
  function* (options: CreatePreviewOptions) {
    const workspace = yield* resolveWorkspace(options.directory)
    const config = yield* loadPreviewConfig(workspace)

    yield* Effect.logInfo(`Creating preview for ${options.branch}`)

    const deployment = yield* uploadPreview({
      workspace,
      projectId: config.projectId,
      branch: options.branch,
      expiresInHours: options.expiresInHours
    })

    const url = previewUrl(config.domain, deployment.id)
    yield* Effect.logInfo(`Preview ready: ${url}`)

    return {
      id: deployment.id,
      url,
      expiresAt: deployment.expiresAt
    }
  }
)
